import{_ as a,o as t,c as s,a9 as i}from"./chunks/framework.asyjyako.js";const k=JSON.parse('{"title":"Real package examples","description":"","frontmatter":{},"headers":[],"relativePath":"real-packages/index.md","filePath":"real-packages/index.md","lastUpdated":null}'),n={name:"real-packages/index.md"};function r(l,e,h,o,p,d){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="Real-package-examples" tabindex="-1">Real package examples <a class="header-anchor" href="#Real-package-examples" aria-label="Permalink to &quot;Real package examples {#Real-package-examples}&quot;">​</a></h1><p>Start with a real workload, prove that its answer is right, then measure the same work across package versions. This section follows that sequence with two packages. You can run the scripts yourself or explore the recorded plots first. An assistant, a hosted service and a GPU are not required.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Example</th><th style="text-align:right;">Work performed</th><th style="text-align:right;">What the measurements include</th></tr></thead><tbody><tr><td style="text-align:right;"><a href="./datastructures">DataStructures</a></td><td style="text-align:right;">Order events, count categories, retain recent events</td><td style="text-align:right;">The selected data-structure operation on a prepared input</td></tr><tr><td style="text-align:right;"><a href="./oxygen">Oxygen</a></td><td style="text-align:right;">Accept the event stream through three HTTP routes</td><td style="text-align:right;">Routing, JSON decoding, the operation and response encoding; a separate recipe adds loopback transport</td></tr></tbody></table><p>The event stream is the same in both examples. It contains a priority, a unique identifier and a category for every event. A fixed seed reproduces the input; an independently computed expected answer checks each workload. This lets you ask whether time is spent processing data or serving the request around it.</p><h2 id="Choose-a-starting-point" tabindex="-1">Choose a starting point <a class="header-anchor" href="#Choose-a-starting-point" aria-label="Permalink to &quot;Choose a starting point {#Choose-a-starting-point}&quot;">​</a></h2><ol><li><p>Read <a href="./datastructures">DataStructures</a> for the smallest complete run.</p></li><li><p>Follow <a href="./oxygen">Oxygen</a> to add a real service and discuss network boundaries.</p></li><li><p><a href="./interfaces">Replay the results</a> in the terminal, Makie, Pluto, Web Studio or VS Code.</p></li><li><p>Add <a href="./extensions">profiles and optional experiments</a> when you have a specific question about a result.</p></li></ol><p>The plots on these pages come from local executions. The documentation build only copies the recorded data and figures. It does <strong>not</strong> install the example environments, start a server or rerun a performance campaign.</p><h2 id="Get-the-runnable-examples" tabindex="-1">Get the runnable examples <a class="header-anchor" href="#Get-the-runnable-examples" aria-label="Permalink to &quot;Get the runnable examples {#Get-the-runnable-examples}&quot;">​</a></h2><p>The scripts are in <a href="https://github.com/Mirage-Interactive-Fr/PerfChecker.jl/tree/release/v1.0.0-rc1/examples/kitchen-sink" target="_blank" rel="noreferrer"><code>examples/kitchen-sink</code></a>. During the release candidate, use a checkout of that branch so the examples and PerfChecker agree. This is preparation for these experiments, not an extra step in <a href="./../guide/installation">installing PerfChecker</a>.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --branch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release/v1.0.0-rc1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Mirage-Interactive-Fr/PerfChecker.jl.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PerfChecker.jl/examples/kitchen-sink</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core</span></span></code></pre></div><p>Run the following commands from this directory. The example controller requires Julia 1.12 or newer. <code>setup.jl core</code> activates this directory&#39;s <code>Project.toml</code>, links the checked-out PerfChecker and installs the example dependencies. Optional interfaces get their own <code>.controller/NAME</code> environments when requested.</p><p>Use one Julia compute thread, one GC thread and one BLAS thread, with one precompilation task. Run campaigns sequentially on an otherwise quiet machine. In PowerShell, for example:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">JULIA_NUM_THREADS </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;1&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">JULIA_NUM_GC_THREADS </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;1&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OPENBLAS_NUM_THREADS </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;1&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">JULIA_NUM_PRECOMPILE_TASKS </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;1&#39;</span></span></code></pre></div><p>These variables bound the components individually; an operating-system affinity or CI CPU allocation bounds the whole process tree. The recorded Windows runs used at most four logical CPUs. They illustrate the workflow on one machine, not a universal performance ranking.</p><h2 id="Understand-the-output" tabindex="-1">Understand the output <a class="header-anchor" href="#Understand-the-output" aria-label="Permalink to &quot;Understand the output {#Understand-the-output}&quot;">​</a></h2><p>A run prints a new directory under <code>results/</code>. It contains <code>suite-result.json</code>, a human-readable report, JUnit output and an integrity-checked run bundle. Keep that directory: every interface can reuse its observations. In command examples, replace <code>results/ACTUAL-RUN</code> with the printed directory.</p><p>Correctness and performance are separate. A successful run means the selected checks and their required oracles passed. A regression verdict additionally requires a baseline, a comparison policy and enough comparable samples. The recorded history does not impose a CI performance budget.</p>`,17)])])}const u=a(n,[["render",r]]);export{k as __pageData,u as default};
